					formattedStack.WriteString("\n    ")
				}
				formattedStack.WriteString(strings.TrimSpace(line))
			}

			r.logging.Error("panic recovered",
				"error", err,
				"method", ctx.Method(),
				"path", ctx.OriginalURL(),
